"""业务目录的唯一冻结事实源；仅合同，不注册处理器、不签票、不授予权限。

来自冻结 interface_contracts.json 的业务 API / schemas，表和 defs 随 Python 包部署。
native 短名与插件名称显式保存；host_mode 不从 effect 推导。结果和 defs 的重复
投影在内嵌表中按精确引用归一，公开副本可完整还原原合同（包括设计状态）。
"""
from __future__ import annotations

import json
from collections.abc import Mapping
from dataclasses import dataclass, field
from functools import lru_cache
from types import MappingProxyType

from .errors import HostAPIError
from .schemas import canonical_json, freeze, thaw, validate_object

# 业务列表省略 limit 时使用的行数；与旧任务目录独立，不能改变旧 schema。
BUSINESS_LIST_DEFAULT_ROWS = 50
# 业务单页行数的硬上限；超限拒绝，不静默裁剪。
BUSINESS_LIST_MAX_ROWS = 100


def business_defs() -> dict:
    """返回完整本地定义表的独立副本，不读部署外的设计文件。"""
    return thaw(_frozen_data()["defs"])


def _references(value):
    if isinstance(value, dict):
        if "$ref" in value:
            ref = value["$ref"]
            if not isinstance(ref, str) or not ref.startswith("#/$defs/"):
                raise ValueError("业务 schema 仅接受本地 defs 引用")
            name = ref[len("#/$defs/"):].replace("~1", "/").replace("~0", "~")
            yield name
        for item in value.values():
            yield from _references(item)
    elif isinstance(value, list):
        for item in value:
            yield from _references(item)


def standalone_schema(schema: Mapping) -> dict:
    """附上传递可达 defs 闭包；递归 JsonValue 只登记一次，绝不展开成引用环。"""
    result = thaw(schema)
    definitions = _frozen_data()["defs"]
    supplied = result.pop("$defs", {})
    if any(name not in definitions or value != thaw(definitions[name]) for name, value in supplied.items()):
        raise ValueError("业务 defs 与冻结合同不一致")
    pending = list(_references(result))
    closure = {}
    while pending:
        name = pending.pop()
        if name in closure:
            continue
        if name not in definitions:
            raise ValueError("业务 schema 缺少本地定义")
        closure[name] = thaw(definitions[name])
        pending.extend(_references(closure[name]))
    if closure:
        result["$defs"] = {name: closure[name] for name in sorted(closure)}
    return result


# LLM: 由business_action_specs装配冻结目录时调用；只改thaw后的独立副本，将指定空间参数投影为NullableId并展开结果/插件schema，不改原目录、不授权或注册处理器。
# 函数用途: 生成一个可独立使用的业务动作合同，保持省略空间与显式null的区别。
def _record(raw: Mapping) -> dict:
    row = thaw(raw)
    # W11沿同一公共Schema演进；省略list过滤仍表示全部，显式null表示Owner无归属。
    if row["action"] in {"background_agents.create", "background_agents.list", "tasks.assign", "tasks.submit"}:
        row["params_schema"]["properties"]["space_id"] = {"$ref": "#/$defs/NullableId"}
    for field_name in ("result_schema", "accepted_result_schema"):
        if field_name in row:
            row[field_name] = thaw(_frozen_data()["defs"][row[field_name]["catalog_def"]])
    if row["plugin_payload_schema"] == {"same_as": "params_schema"}:
        row["plugin_payload_schema"] = thaw(row["params_schema"])
    return row


@dataclass(frozen=True)
class BusinessActionSpec:
    """一个 native 业务动作及其精确插件投影；构造此对象没有授权效力。"""

    action: str
    plugin_action: str
    host_mode: str
    capabilities: frozenset[str]
    scope_requirements: tuple[str, ...]
    _record_json: str = field(repr=False)

    @property
    def metadata(self) -> dict:
        return json.loads(self._record_json)

    @property
    def requires_idempotency(self) -> bool:
        return self.metadata["idempotency_required"]

    @property
    def expected_revision_required(self) -> bool:
        return self.metadata["expected_revision_required"]

    @property
    def human_authorization_required(self) -> bool:
        return self.metadata["human_authorization_required"]

    @property
    def conditional_capabilities(self) -> dict:
        # 条件中的跨人身份必须来自 Issuer，不接受模型 payload 自报。
        return self.metadata["conditional_capabilities"]

    @property
    def params_schema(self) -> dict:
        return standalone_schema(self.metadata["params_schema"])

    @property
    def plugin_payload_schema(self) -> dict:
        return standalone_schema(self.metadata["plugin_payload_schema"])

    @property
    def result_schema(self) -> dict:
        return standalone_schema(self.metadata["result_schema"])

    @property
    def accepted_result_schema(self) -> dict | None:
        schema = self.metadata.get("accepted_result_schema")
        return standalone_schema(schema) if schema is not None else None

    @property
    def native_request_schema(self) -> dict:
        request = thaw(_frozen_data()["native_requests"][self.action])
        request["properties"]["params"] = self.metadata["params_schema"]
        return standalone_schema(request)

    def validate_result(self, value: object, *, accepted: bool = False) -> dict:
        """调用者按请求 action/实际阶段选择；202 不能冒充 completed DTO。"""
        schema = self.accepted_result_schema if accepted else self.result_schema
        if schema is None:
            raise HostAPIError("INVALID_SCHEMA")
        return validate_object(value, schema)


@lru_cache(maxsize=1)
def business_action_specs() -> Mapping[str, BusinessActionSpec]:
    rows = [_record(row) for row in _frozen_data()["actions"]]
    if len({row["action"] for row in rows}) != len(rows) or len({row["plugin_action"] for row in rows}) != len(rows):
        raise ValueError("业务动作映射重名")
    return MappingProxyType({row["action"]: BusinessActionSpec(
        row["action"], row["plugin_action"], row["host_mode"], frozenset(row["capabilities"]),
        tuple(row["scope_requirements"]), canonical_json(row)) for row in rows})


def business_action_spec(action: str) -> BusinessActionSpec:
    if not isinstance(action, str) or action not in business_action_specs():
        raise HostAPIError("UNSUPPORTED_ACTION")
    return business_action_specs()[action]


def business_plugin_action(native_action: str) -> str:
    return business_action_spec(native_action).plugin_action


@lru_cache(maxsize=1)
def business_plugin_actions() -> frozenset[str]:
    """静态目录集合，含独立运输动作；不缓存权限、Owner或动态ready。"""
    return frozenset({spec.plugin_action for spec in business_action_specs().values()} | {'business.events.stream'})


def business_native_action(plugin_action: str) -> str:
    # 不通过 removeprefix 猜测；stream 是独立 transport-only spec，不在双射内。
    for spec in business_action_specs().values():
        if spec.plugin_action == plugin_action:
            return spec.action
    raise HostAPIError("UNSUPPORTED_ACTION")


def business_capabilities() -> frozenset[str]:
    """manifest/grant 共同消费的词汇，不是任何安装的默认批准集合。"""
    return frozenset(_frozen_data()["api_metadata"]["capability_vocabulary"])


def business_host_action_specs() -> list:
    """投影到现有 ActionSpec；惰性导入防止中央目录互相导入。"""
    from .action_specs import ActionSpec

    specs = [ActionSpec(spec.plugin_action, spec.host_mode, spec.capabilities,
                        canonical_json(spec.plugin_payload_schema), spec.scope_requirements)
             for spec in business_action_specs().values()]
    for row in _frozen_data()["api_metadata"]["transport_only_action_specs"]:
        specs.append(ActionSpec(row["plugin_action"], row["host_mode"], frozenset(row["capabilities"]),
                                canonical_json(standalone_schema(row["plugin_payload_schema"])),
                                tuple(row["scope_requirements"])))
    return specs


def business_api() -> dict:
    """完整冻结 API 副本；status 保留设计状态，不宣称领域已实现。"""
    return {**thaw(_frozen_data()["api_metadata"]), "$defs": business_defs(),
            "actions": [spec.metadata for spec in business_action_specs().values()]}


def business_schema_bundle() -> dict:
    """完整冻结 schemas 副本；需要单独校验时须使用 standalone_schema。"""
    branches = []
    for spec in business_action_specs().values():
        branch = spec.native_request_schema
        branch.pop("$defs", None)
        branches.append(branch)
    return {**thaw(_frozen_data()["schema_metadata"]), "$defs": business_defs(),
            "event_schema": thaw(_frozen_data()["defs"]["EventView"]),
            "request_schema": {"$schema": _frozen_data()["request_schema_version"], "oneOf": branches}}


# 下方是冻结 JSON 的机械内嵌 Python 表；生成时按完整结构比较并固定测试摘要。
# 这不是配置加载器；运行时不读取任何任务文件、工作目录或外部 schema。


